import jdk.incubator.concurrent.ScopedValue;

public class ScopedValueExample {
    // Define a static final ScopedValue instance
    private static final ScopedValue<String> CURRENT_USER = ScopedValue.newInstance();

    public void handleRequest(String username) {
        // Bind the ScopedValue lexically for the duration of the run block
        ScopedValue.where(CURRENT_USER, username).run(() -> {
            processSubTask();
        });
    }

    private void processSubTask() {
        // Access the immutable scoped value safely without explicit parameters
        String user = CURRENT_USER.get();
        System.out.println("Processing request for user: " + user);
    }
}
